15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java((owner.getFirstName().substring(0, 1) + \".\" + owner.getLastName().substring(0, 1) + \".\").toUpperCase())")
25	    @Mapping(target = "membershipNumber",
26	        expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
27	    @Mapping(target = "membershipLevel",
28	        expression = "java(Math.min(3, 1 + (owner.getEmail() != null ? 1 : 0) + (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0 ? 1 : 0)))")
29	    @Mapping(target = "locality",
30	        expression = "java(switch (owner.getCity()) { case \"Sydney\" -> \"NSW\"; case \"Melbourne\" -> \"VIC\"; case \"Brisbane\" -> \"QLD\"; default -> \"UNKNOWN\"; })")
31	    OwnerDto toOwnerDto(Owner owner);
32	
33	    Owner toOwner(OwnerDto ownerDto);
34	
35	    @Mapping(target = "id", ignore = true)
36	    @Mapping(target = "pets", ignore = true)
37	    Owner toOwner(OwnerFieldsDto ownerDto);
38	
39	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
40	
41	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
42	
43	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
44	        OwnerPageDto ownerPageDto = new OwnerPageDto();
45	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
46	        ownerPageDto.setPage(ownerPage.getNumber());
47	        ownerPageDto.setSize(ownerPage.getSize());
48	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
49	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
50	        return ownerPageDto;
51	    }
52	}
