149	
150	    protected Set<Pet> getPetsInternal() {
151	        if (this.pets == null) {
152	            this.pets = new HashSet<>();
153	        }
154	        return this.pets;
155	    }
156	
157	    protected void setPetsInternal(Set<Pet> pets) {
158	        this.pets = pets;
159	    }
160	
161	    public List<Pet> getPets() {
162	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
163	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
164	        return Collections.unmodifiableList(sortedPets);
165	    }
166	
167	    public void setPets(List<Pet> pets) {
168	        this.pets = new HashSet<>(pets);
169	    }
170	
171	    public void addPet(Pet pet) {
172	        getPetsInternal().add(pet);
173	        pet.setOwner(this);
174	    }
175	
176	    /**
177	     * Return the Pet with the given name, or null if none found for this Owner.
178	     *
179	     * @param name to test
180	     * @return true if pet name is already in use
181	     */
182	    public Pet getPet(String name) {
183	        return getPet(name, false);
184	    }
185	
186	    /**
187	     * Return the Pet with the given name, or null if none found for this Owner.
188	     *
189	     * @param name to test
190	     * @return true if pet name is already in use
191	     */
192	    public Pet getPet(String name, boolean ignoreNew) {
193	        name = name.toLowerCase();
194	        for (Pet pet : getPetsInternal()) {
195	            if (!ignoreNew || !pet.isNew()) {
196	                String compName = pet.getName();
197	                compName = compName.toLowerCase();
198	                if (compName.equals(name)) {
199	                    return pet;
200	                }
201	            }
202	        }
203	        return null;
204	    }
205	
206	    public Pet getPet(Integer petId) {
207	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
208	    }
209	
210	    @Override
211	    public String toString() {
212	        return new ToStringCreator(this)
213	
214	            .append("id", this.getId())
215	            .append("new", this.isNew())
216	            .append("lastName", this.getLastName())
217	            .append("firstName", this.getFirstName())
218	            .append("address", this.address)
219	            .append("city", this.city)
220	            .append("telephone", this.telephone)
221	            .toString();
222	    }
